// Generated by Jjodel from the model cpu with the hw-cpu templates (route A of the hardware demonstrator).
// One control state is one clock cycle: its exit actions are the register transfers of the cycle, printed from the
// JjEL texts the simulator runs, and its transitions choose the next state. The initial block is the configuration
// Reset gives in the simulator.
module cpu (
  input wire clk,
  output reg [3:0] state,
  output reg [3:0] pc,
  output reg [7:0] ir,
  output reg [7:0] acc,
  output reg [0:0] z
);
  localparam [3:0] FETCH = 4'h0;
  localparam [3:0] DECODE = 4'h1;
  localparam [3:0] EX_LDA = 4'h2;
  localparam [3:0] EX_STA = 4'h3;
  localparam [3:0] EX_ADD = 4'h4;
  localparam [3:0] EX_SUB = 4'h5;
  localparam [3:0] EX_AND = 4'h6;
  localparam [3:0] EX_LDI = 4'h7;
  localparam [3:0] EX_JZ = 4'h8;
  localparam [3:0] EX_JMP = 4'h9;
  localparam [3:0] HALT = 4'ha;

  reg [7:0] rom [0:15];
  reg [7:0] ram [0:15];

  initial begin
    state = FETCH;
    pc = 4'h0;
    ir = 8'h00;
    acc = 8'h00;
    z = 1'h0;
    rom[0] = 8'h61;
    rom[1] = 8'h2f;
    rom[2] = 8'h66;
    rom[3] = 8'h2e;
    rom[4] = 8'h67;
    rom[5] = 8'h2d;
    rom[6] = 8'h1e;
    rom[7] = 8'h7e;
    rom[8] = 8'h4f;
    rom[9] = 8'h2e;
    rom[10] = 8'h1c;
    rom[11] = 8'h3d;
    rom[12] = 8'h2c;
    rom[13] = 8'h86;
    rom[14] = 8'hf0;
    rom[15] = 8'h00;
    ram[0] = 8'h00;
    ram[1] = 8'h00;
    ram[2] = 8'h00;
    ram[3] = 8'h00;
    ram[4] = 8'h00;
    ram[5] = 8'h00;
    ram[6] = 8'h00;
    ram[7] = 8'h00;
    ram[8] = 8'h00;
    ram[9] = 8'h00;
    ram[10] = 8'h00;
    ram[11] = 8'h00;
    ram[12] = 8'h00;
    ram[13] = 8'h00;
    ram[14] = 8'h00;
    ram[15] = 8'h00;
  end

  always @(posedge clk) begin
    case (state)
      FETCH: begin
        ir <= rom[pc];
        pc <= pc + 4'h1;
        state <= DECODE;
      end
      DECODE: begin
        if (ir[7:4] == 4'h0) begin
          state <= FETCH;
        end else if (ir[7:4] == 4'h1) begin
          state <= EX_LDA;
        end else if (ir[7:4] == 4'h2) begin
          state <= EX_STA;
        end else if (ir[7:4] == 4'h3) begin
          state <= EX_ADD;
        end else if (ir[7:4] == 4'h4) begin
          state <= EX_SUB;
        end else if (ir[7:4] == 4'h5) begin
          state <= EX_AND;
        end else if (ir[7:4] == 4'h6) begin
          state <= EX_LDI;
        end else if (ir[7:4] == 4'h7) begin
          state <= EX_JZ;
        end else if (ir[7:4] == 4'h8) begin
          state <= EX_JMP;
        end else if (ir[7:4] == 4'hf) begin
          state <= HALT;
        end else begin
          state <= FETCH;
        end
      end
      EX_LDA: begin
        acc <= ram[ir[3:0]];
        z <= (ram[ir[3:0]] == 8'h00) ? 1'h1 : 1'h0;
        state <= FETCH;
      end
      EX_STA: begin
        ram[ir[3:0]] <= acc;
        state <= FETCH;
      end
      EX_ADD: begin
        acc <= acc + ram[ir[3:0]];
        z <= ({acc + ram[ir[3:0]]} == 8'h00) ? 1'h1 : 1'h0;
        state <= FETCH;
      end
      EX_SUB: begin
        acc <= acc - ram[ir[3:0]];
        z <= ({acc - ram[ir[3:0]]} == 8'h00) ? 1'h1 : 1'h0;
        state <= FETCH;
      end
      EX_AND: begin
        acc <= acc & ram[ir[3:0]];
        z <= ({acc & ram[ir[3:0]]} == 8'h00) ? 1'h1 : 1'h0;
        state <= FETCH;
      end
      EX_LDI: begin
        acc <= ir[3:0];
        z <= ({8'(ir[3:0])} == 8'h00) ? 1'h1 : 1'h0;
        state <= FETCH;
      end
      EX_JZ: begin
        pc <= (z == 1'h1) ? ir[3:0] : pc;
        state <= FETCH;
      end
      EX_JMP: begin
        pc <= ir[3:0];
        state <= FETCH;
      end
      HALT: begin
      end
      default: begin
      end
    endcase
  end
endmodule
